INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(45111, 'Proverbs 30:6', 'Proverbs', 30, 6, 'د هغه په کلام کې یو توری هم مه زیاتوه هسې نه چې هغه دې ورټي او تا دروغجن ثابت کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs30_verse_6.mp3', '', 1761754199, 1761754199),
(45112, 'Proverbs 30:7', 'Proverbs', 30, 7, 'نو ای خدایه! ستا نه دوه شیان غواړم ترڅو مړ شوی نه یم له ما نه یې مه منع کوه:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs30_verse_7.mp3', '', 1761754199, 1761754199),
(45113, 'Proverbs 30:8', 'Proverbs', 30, 8, 'ما د دروغو او غولوونکو خبرو نه لېرې وساته. ماته ډېره شتمني او ډېره غریبي مه راکوه خو ماته یوازې د هرې ورځې ډوډۍ راکړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs30_verse_8.mp3', '', 1761754199, 1761754199),
(45114, 'Proverbs 30:9', 'Proverbs', 30, 9, 'هسې نه چې زه موړ شم او ستا نه منکر شم او ووایم چې څښتن څوک دی؟ او یا زه غریب شم او غلا وکړم او ستا نوم ته په سپکه سترګه وکتل شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs30_verse_9.mp3', '', 1761754199, 1761754199),
(45115, 'Proverbs 30:10', 'Proverbs', 30, 10, 'د بادار په مخکې په یو خدمتګار تور مه لګوه هسې نه چې هغه په تا لعنت ووایي او تا ملامت کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs30_verse_10.mp3', '', 1761754199, 1761754199),
(45116, 'Proverbs 30:11', 'Proverbs', 30, 11, 'داسې خلک هم شته چې په خپل پلار لعنت وایي او خپله مور مبارکه نه ګڼي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs30_verse_11.mp3', '', 1761754199, 1761754199),
(45117, 'Proverbs 30:12', 'Proverbs', 30, 12, 'داسې خلک هم شته چې خپل ځان بې‌ګناه ګڼي خو د بدن چټلي یې لا پاکه شوې نه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs30_verse_12.mp3', '', 1761754199, 1761754199),
(45118, 'Proverbs 30:13', 'Proverbs', 30, 13, 'داسې خلک هم شته چې سترګې یې له کبر نه ډکې دي او نورو ته تل په سپکه سترګه ګوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs30_verse_13.mp3', '', 1761754199, 1761754199),
(45119, 'Proverbs 30:14', 'Proverbs', 30, 14, 'داسې خلک هم شته چې غاښونه یې د تورو په شان تېره دي او داړې یې د چړو په څېر تېرې دي ترڅو د غریبانو غوښې پرې وخوري او مسکینان د ځمکې د مخ نه ختم کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs30_verse_14.mp3', '', 1761754199, 1761754199),
(45120, 'Proverbs 30:15', 'Proverbs', 30, 15, 'د یوې ژورې دوه لورګانې دي: لومړنۍ وایي چې «راکړه!» او بله هم وایي چې «راکړه!» درې شیان دي چې هېڅکله نه مړیږي او څلور شیان دي چې هېڅکله «بس!» نه وایي:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs30_verse_15.mp3', '', 1761754199, 1761754199),
(45121, 'Proverbs 30:16', 'Proverbs', 30, 16, 'قبر او د شنډې ښځې ګېډه او وچه ځمکه چې تنده یې نه ماتیږي او سوځېدونکی اور چې هېڅکله «بس!» نه وایي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs30_verse_16.mp3', '', 1761754199, 1761754199),
(45122, 'Proverbs 30:17', 'Proverbs', 30, 17, 'هغه سترګې چې په خپل پلار باندې ملنډې وهي او د خپلې مور نصیحت ته په سپکه ګوري نو د تنګو درو کارغان به یې سترګې راوباسي او د ټپوسانو خوراک به شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs30_verse_17.mp3', '', 1761754199, 1761754199),
(45123, 'Proverbs 30:18', 'Proverbs', 30, 18, 'درې حیرانوونکې شیان دي او څلور شیان دي چې زما دپاره د پېژندلو وړ نه دي:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs30_verse_18.mp3', '', 1761754199, 1761754199),
(45124, 'Proverbs 30:19', 'Proverbs', 30, 19, 'په هوا کې عقاب څنګه الوزي او په تیږه باندې مار څنګه ځي په دریابونو کې کشتۍ څنګه لار پیدا کوي او د یوې ځوانې ښځې سره یو ځوان څنګه یوځای کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs30_verse_19.mp3', '', 1761754199, 1761754199),
(45125, 'Proverbs 30:20', 'Proverbs', 30, 20, 'دا د زناکارې ښځې طریقه ده: چې کله خواړه خوري او بیا خوله پاکوي او وایي چې ما خو کوم بد کار نه دی کړی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs30_verse_20.mp3', '', 1761754199, 1761754199),
(45126, 'Proverbs 30:21', 'Proverbs', 30, 21, 'درې شیان دي چې ځمکه لړزوي او څلور شیان دي چې هغه یې هېڅکله زغملی نه شي:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs30_verse_21.mp3', '', 1761754199, 1761754199),
(45127, 'Proverbs 30:22', 'Proverbs', 30, 22, 'کله چې یو خدمتګار پاچا شي او بې‌عقله چې په ګېډه موړ شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs30_verse_22.mp3', '', 1761754199, 1761754199),
(45128, 'Proverbs 30:23', 'Proverbs', 30, 23, 'کله چې د کرکې وړ ښځه واده شي او کومه وینځه چې د کور د مېرمن بن شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs30_verse_23.mp3', '', 1761754199, 1761754199),
(45129, 'Proverbs 30:24', 'Proverbs', 30, 24, 'څلور شیان دي چې په ځمکه ډېر واړه دي خو ډېر زیات هوښیار دي:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs30_verse_24.mp3', '', 1761754199, 1761754199),
(45130, 'Proverbs 30:25', 'Proverbs', 30, 25, 'میږیان یو کمزوری مخلوق دی خو په اوړي کې ځان ته خواړه راټولوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs30_verse_25.mp3', '', 1761754199, 1761754199),
(45131, 'Proverbs 30:26', 'Proverbs', 30, 26, 'غرنۍ سویه یو کمزوری حیوان دی خو د غره په کلکو ګړنګونو کې کور جوړوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs30_verse_26.mp3', '', 1761754199, 1761754199),
(45132, 'Proverbs 30:27', 'Proverbs', 30, 27, 'د ملخانو پاچا او مشر نه وي خو د لښکر په شان سم روان وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs30_verse_27.mp3', '', 1761754199, 1761754199),
(45133, 'Proverbs 30:28', 'Proverbs', 30, 28, 'که چرمښکۍ په لاس کې نیول کېدلی شي خو په پاچاهي ماڼیو کې هم ګرځېدلی شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs30_verse_28.mp3', '', 1761754199, 1761754199),
(45134, 'Proverbs 30:29', 'Proverbs', 30, 29, 'درې شیان دي چې په ناز تلل کوي او څلور شیان دي چې په نخرو درانه قدمونه اخلي:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs30_verse_29.mp3', '', 1761754199, 1761754199),
(45135, 'Proverbs 30:30', 'Proverbs', 30, 30, 'زمری چې په ټولو ځناورو کې قوي دی او د هېڅ شي څخه نه وېریږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs30_verse_30.mp3', '', 1761754199, 1761754199),
(45136, 'Proverbs 30:31', 'Proverbs', 30, 31, 'جنګي چرګ او سېرلی او هغه پاچا چې هېڅوک یې مخالفت نه شي کولای.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs30_verse_31.mp3', '', 1761754199, 1761754199),
(45137, 'Proverbs 30:32', 'Proverbs', 30, 32, 'که ته د بې‌عقلتوب په خبرو ځان لوړ ګڼې او یا چاته دسیسه جوړوې نو په خپله خوله باندې دې لاس کېږده', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs30_verse_32.mp3', '', 1761754199, 1761754199),
(45138, 'Proverbs 30:33', 'Proverbs', 30, 33, 'ځکه چې د مستو د شاربلو نه کوچ جوړیږي او په پوزه باندې د ګوزار وهلو نه وینه بهیږي همداسې د غوسې د راپارولو نه جګړه پیدا کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs30_verse_33.mp3', '', 1761754199, 1761754199),
(45139, 'Numbers 18:1', 'Numbers', 18, 1, 'څښتن هارون ته داسې وویل: «هرڅه چې په سپېڅلې خېمه کې پېښیږي ته، ستا زامن او نور لاویان د هغو په وړاندې مسوول یئ، خو څه چې کاهنان کوي د هغه په وړاندې یوازې ته او ستا زامن مسوولیت لرئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers18_verse_1.mp3', '', 1761754199, 1761754199),
(45140, 'Numbers 18:2', 'Numbers', 18, 2, 'خپل خپلوان یعنې لاویان راوله چې ستا سره کار وکړي او ستا او ستا د زامنو سره د خېمې په کار کې مرسته وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers18_verse_2.mp3', '', 1761754199, 1761754199),
(45141, 'Numbers 18:3', 'Numbers', 18, 3, 'هغوی به تاته مسوول وي او د سپېڅلې خېمې ټولې وظیفې به تر سره کوي، خو هغوی باید د قربانۍ ځای یا هغو پاکو شیانو ته چې په سپېڅلي ځای کې دي نژدې ورنه شي. که چېرې دا کار وکړي، نو هغوی او تاسو به ووژل شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers18_verse_3.mp3', '', 1761754199, 1761754199),
(45142, 'Numbers 18:4', 'Numbers', 18, 4, 'هغوی باید تاسو سره کار وکړي او د خېمې د ټولو کارونو په اړه دې خپل مسوولیت تر سره کړي، خو بل هېڅوک نه شي کولای چې تاسو سره کار وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers18_verse_4.mp3', '', 1761754199, 1761754199),
(45143, 'Numbers 18:5', 'Numbers', 18, 5, 'یوازې ته او ستا زامن باید د سپېڅلي ځای او د قربانۍ د ځای دپاره وظیفې اجرا کړئ، ترڅو زما قهر بیا د اسراییلو په قوم باندې نازل نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers18_verse_5.mp3', '', 1761754199, 1761754199),
(45144, 'Numbers 18:6', 'Numbers', 18, 6, 'دا زه یم چې ستاسو خپلوان لاویان مې تاسو ته د مرستیالانو په توګه د اسراییلیانو څخه غوره کړي دي. هغوی ماته وقف شوي دي، ترڅو وکولای شي چې په سپېڅلې خېمه کې خپلې وظیفې سرته ورسوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers18_verse_6.mp3', '', 1761754199, 1761754199),
(45145, 'Numbers 18:7', 'Numbers', 18, 7, 'خو یوازې ته او ستا زامن کولای شئ چې د قربانۍ په ځای او ډېر سپېڅلي ځای کې د کاهنانو په توګه خدمت وکړئ. د کاهنانو په توګه ستاسو کار زما له خوا تاسو ته یو سوغات دی او که بل څوک هڅه وکړي چې دا کار وکړي، هغه باید ووژل شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers18_verse_7.mp3', '', 1761754199, 1761754199),
(45146, 'Numbers 18:8', 'Numbers', 18, 8, 'څښتن هارون ته وویل: «دا په یاد وساته چې زه تاته هغه نذرانې درکوم، یعنې هغه ټولې ځانګړې نذرانې چې اسراییلیان یې ماته راکوي او د قربانیو په توګه نه سوځول کیږي. زه هغه تا او ستا اولادې ته د هغې برخې په توګه درکوم چې تل ترتله به درکول کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers18_verse_8.mp3', '', 1761754199, 1761754199),
(45147, 'Numbers 18:9', 'Numbers', 18, 9, 'د ډېرو سپېڅلو نذرانو څخه چې د قربانۍ په ځای باندې نه سوځول کیږي، دا لاندېنۍ نذرانې ستاسو دي: د غلې دانې نذرانې، د ګناه نذرانې او د تاوان نذرانې. هرڅه چې ماته د یوې سپېڅلې نذرانې په توګه وړاندې کیږي، هغه ستا او ستا د زامنو دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers18_verse_9.mp3', '', 1761754199, 1761754199),
(45148, 'Numbers 18:10', 'Numbers', 18, 10, 'څرنګه چې دا شیان سپېڅلي دي، نو باید په سپېڅلي ځای کې وخوړل شي، خو یوازې نارینه اجازه لري چې هغه وخوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers18_verse_10.mp3', '', 1761754199, 1761754199),
(45149, 'Numbers 18:11', 'Numbers', 18, 11, 'برسېره پردې، نورې ځانګړې نذرانې چې اسراییلیان یې ماته وړاندې کوي هغه به ستا وي. هغه به د تل دپاره تا، ستا زامنو او ستا لورګانو ته درکوم. ستا د کورنۍ هر غړی چې په مذهبي لحاظ پاک وي، هغه خوړلی شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers18_verse_11.mp3', '', 1761754199, 1761754199),
(45150, 'Numbers 18:12', 'Numbers', 18, 12, 'د هغو ټولو لومړنیو ښو محصولاتو څخه چې اسراییلیان یې هر کال ماته راکوي زه یې تاسو ته درکوم، یعنې د زیتونو تېل، شراب او غلې دانې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers18_verse_12.mp3', '', 1761754199, 1761754199),
(45151, 'Numbers 18:13', 'Numbers', 18, 13, 'د هغوی د پټیو او د انګورو د باغونو د فصلونو لومړنۍ برخه هم ستاسو ده. قوم به هغه ماته وړاندې کړي، بیا هرڅوک چې ستاسو په کورنۍ کې پاک وي د هغې څخه لږه اخیستلی شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers18_verse_13.mp3', '', 1761754199, 1761754199),
(45152, 'Numbers 18:14', 'Numbers', 18, 14, 'هرڅه چې په اسراییلو کې بې له کوم قید او شرط څخه ماته وقف شوي وي ستاسو به شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers18_verse_14.mp3', '', 1761754199, 1761754199),
(45153, 'Numbers 18:15', 'Numbers', 18, 15, 'په هرې اسراییلي کورنۍ کې مشر زوی او د هغوی د رمو او پادو لومړني زېږېدلي نران حیوانات زما دي. خو مشر زوی او هر لومړنی زېږېدلی ناپاک نر حیوان باید بېرته په بیه واخیستل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers18_verse_15.mp3', '', 1761754199, 1761754199),
(45154, 'Numbers 18:16', 'Numbers', 18, 16, 'د مشر زوی بیه به چې لږ تر لږه د یوې میاشتې وي، پنځه د سپینو زرو سکې وي چې وزن یې د سپېڅلي ځای د اندازې له مخې وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers18_verse_16.mp3', '', 1761754199, 1761754199),
(45155, 'Numbers 18:17', 'Numbers', 18, 17, 'خو د غواګانو، مېږو او وزو لومړني زېږېدلي بچي بېرته په بیه نه اخیستل کیږي. هغه بیخي زما دي او باید قرباني شي. وینه یې د قربانۍ په ځای باندې وشیندئ او وازګه یې د داسې نذرانې په توګه وسوځوئ چې په اور باندې تیاریږي، دا بوی په څښتن باندې ښه لګیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers18_verse_17.mp3', '', 1761754199, 1761754199),
(45156, 'Numbers 18:18', 'Numbers', 18, 18, 'تاسو کولای شئ چې د دې حیواناتو غوښه وخورئ لکه څنګه چې د ځانګړې نذرانې سینه او شاتنۍ ښي پښه خوړلی شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers18_verse_18.mp3', '', 1761754199, 1761754199),
(45157, 'Numbers 18:19', 'Numbers', 18, 19, 'هغه ټولې ځانګړې نذرانې چې اسراییلیان یې ماته وړاندې کوي هغه به تل تا، ستا زامنو او لورګانو ته درکوم. دا یو نه ماتېدونکی لوظ دی چې زه یې تا او ستا د اولادې سره کوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers18_verse_19.mp3', '', 1761754199, 1761754199),
(45158, 'Numbers 18:20', 'Numbers', 18, 20, 'تاسو ته به په اسراییلو کې ځمکه درنه کړل شي چې ستاسو میراث شي او نه به د جایداد کومه برخه درکړل شي. زه څښتن یم او زه ستاسو دپاره هم برخه یم او هم ستاسو میراث.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers18_verse_20.mp3', '', 1761754199, 1761754199),
(45159, 'Numbers 18:21', 'Numbers', 18, 21, 'څښتن هارون ته وویل: «د اسراییلیانو لس فیصده فصلونه او د هرو لسو نویو زېږېدلو حیواناتو څخه یو حیوان زما دی. خو دا ټول لاویانو ته د هغوی د کار او خدمت په بدل کې چې په سپېڅلې خېمه کې یې کوي، ورکوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers18_verse_21.mp3', '', 1761754199, 1761754199),
(45160, 'Numbers 18:22', 'Numbers', 18, 22, 'نور اسراییلیان باید خېمې ته ورنژدې نه شي او په دې ډول دې خپل ځانونه د مرګ سزا ته نه جوړوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers18_verse_22.mp3', '', 1761754199, 1761754199),
(45161, 'Numbers 18:23', 'Numbers', 18, 23, 'له همدې وخت څخه به یوازې لاویان په خېمې باندې پام کوي او د هغې پوره مسوولیت به په غاړه اخلي. دا تلپاتې اصول دي چې ستاسو په اولادې باندې به هم عملي کیږي. لاویان باید په اسراییلو کې خپله ځمکه ونه لري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers18_verse_23.mp3', '', 1761754199, 1761754199),
(45162, 'Numbers 18:24', 'Numbers', 18, 24, 'د هغې په ځای به هغوی ته هغه حاصلات او هغه نوي زېږېدلي حیوانات ورکول کیږي چې اسراییلیان یې ماته وړاندې کوي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers18_verse_24.mp3', '', 1761754199, 1761754199),
(45163, 'Numbers 18:25', 'Numbers', 18, 25, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers18_verse_25.mp3', '', 1761754199, 1761754199),
(45164, 'Numbers 18:26', 'Numbers', 18, 26, '«لاویانو ته داسې ووایه: ‹کله چې تاسو د اسراییلیانو څخه د حاصلاتو او نوي زېږېدلو حیواناتو عشر واخلئ، باید د هغو عشر ما څښتن ته وړاندې کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers18_verse_26.mp3', '', 1761754199, 1761754199),
(45165, 'Numbers 18:29', 'Numbers', 18, 29, 'نو څه چې تاسو اخلئ، ډېره ښه برخه به یې زما وي.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers18_verse_29.mp3', '', 1761754199, 1761754199),
(45166, 'Numbers 18:30', 'Numbers', 18, 30, 'لاویانو ته داسې هم ووایه: ‹کله چې تاسو ډېره ښه برخه وړاندې کړه، نو کولای شئ چې پاتې برخه یې خپل ځان ته وساتئ، لکه څنګه چې بزګر د نذرانې ورکولو څخه وروسته څه چې پاتې شوي وي هغه ساتي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers18_verse_30.mp3', '', 1761754199, 1761754199),
(45167, 'Numbers 18:31', 'Numbers', 18, 31, 'تاسو او ستاسو کورنۍ کولای شئ چې پاتې شوې برخه په هرځای کې وخورئ، ځکه چې دا په سپېڅلې خېمه کې د کار کولو دپاره ستاسو اجوره ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers18_verse_31.mp3', '', 1761754199, 1761754199),
(45168, 'Numbers 18:32', 'Numbers', 18, 32, 'د هغې په خوړلو به تاسو ته سزا نه درکول کیږي په دې شرط چې تاسو مخکې ماته ډېرې ښې برخې وړاندې کړې وي. هغه سوغاتونه او قربانۍ چې قوم یې راوړي باید سپېڅلې پاتې شي او مخکې له دې چې ماته وړاندې شي، که تاسو د هغو څخه کومه برخه وخورئ، نو وبه وژل شئ.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers18_verse_32.mp3', '', 1761754199, 1761754199),
(45169, 'Jeremiah 51:1', 'Jeremiah', 51, 1, 'مالِک خُدائ داسې فرمائى چې، ”ګوره، زۀ به د بابل او د هغۀ د خلقو خلاف تباه کوونکې هوا راوچته کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_1.mp3', '', 1761754199, 1761754199),
(45170, 'Jeremiah 51:2', 'Jeremiah', 51, 2, 'زۀ به بابل ته غېر مُلکيان ورولېږم چې هغه چاڼ کړى او د هغۀ مُلک تباه کړى. او هغوئ به په هغۀ د هرې خوا نه حمله وکړى کله چې د هغۀ د تباهۍ ورځ راشى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_2.mp3', '', 1761754199, 1761754199),
(45171, 'Jeremiah 51:3', 'Jeremiah', 51, 3, 'د بابل فوجيان ليندو راښکلو ته مۀ پرېږدئ، او زغرو اچولو ته يې مۀ پرېږدئ. د هغوئ ځوانان درنه بچ نۀ شى، د هغوئ فوجيان په مکمل توګه تباه کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_3.mp3', '', 1761754199, 1761754199),
(45172, 'Jeremiah 51:4', 'Jeremiah', 51, 4, 'هغوئ به په بابل کښې مړۀ شى، او د هغۀ په کوڅو کښې به سخت زخميان شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_4.mp3', '', 1761754199, 1761754199),
(45173, 'Jeremiah 51:5', 'Jeremiah', 51, 5, 'خو اِسرائيل او يهوداه خُدائ پاک ربُ الافواج نۀ دى هېر کړى، کۀ څۀ هم چې د هغوئ مُلک د بنى اِسرائيلو د مقدس ذات په خلاف د ګناه نه ډک دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_5.mp3', '', 1761754199, 1761754199),
(45174, 'Jeremiah 51:6', 'Jeremiah', 51, 6, 'د بابل نه وتښتئ، د خپل ژوند د بچ کولو دپاره منډه ووهئ، د هغۀ د ګناهونو په وجه خپل ځان مۀ مړ کوئ. دا د مالِک خُدائ د انتقام وخت دے، هغه به ورته پوره بدل ورکړى د کوم چې بابل حقدار وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_6.mp3', '', 1761754199, 1761754199),
(45175, 'Jeremiah 51:7', 'Jeremiah', 51, 7, 'بابل د مالِک خُدائ په لاس کښې د سرو زرو پياله وه، هغه پيالۍ چې ټوله زمکه يې نشه کړه. قومونو د هغۀ شراب وڅښل نو په دې وجه هغوئ اوس مست شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_7.mp3', '', 1761754199, 1761754199),
(45176, 'Jeremiah 51:8', 'Jeremiah', 51, 8, 'خو ناګهانه بابل هم راوغورزېدو په هغۀ ماتم وکړئ. د هغۀ زخمونو له مرهم ورکړئ. کېدے شى چې هغه شفا ومومى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_8.mp3', '', 1761754199, 1761754199),
(45177, 'Jeremiah 51:9', 'Jeremiah', 51, 9, 'مونږ به هغۀ ته شفا ورکړې وه کۀ چرې مونږ کولے شو، خو هغه اوس نۀ رغيږى. راځئ چې اوس هغه پرېږدو او هر يو خپل مُلک ته واپس لاړ شُو، د هغۀ سزا اوس آسمان ته رسېدلې ده، دا دومره لويه ده چې هغه اوس د اندازه کولو نه بهر ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_9.mp3', '', 1761754199, 1761754199),
(45178, 'Jeremiah 51:10', 'Jeremiah', 51, 10, 'مالِک خُدائ دا خبره څرګنده کړه چې مونږ په حقه يُو. راځئ چې په صيون کښې هغه څۀ ووايو کوم کارونه چې مالِک خُدائ زمونږ خُدائ پاک کړى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_10.mp3', '', 1761754199, 1761754199),
(45179, 'Jeremiah 51:11', 'Jeremiah', 51, 11, 'خپل غشى تېرۀ کړئ، او خپل ډالونه راوچت کړئ، مالِک خُدائ دا مادى بادشاهان راوچت کړى دى، چې د بابل خلاف پېش قدمى وکړى او هغه تباه کړى. دا د هغۀ انتقام اخستل دى د هغه چا نه چا چې د هغۀ کور پليت کړے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_11.mp3', '', 1761754199, 1761754199),
(45180, 'Jeremiah 51:12', 'Jeremiah', 51, 12, 'د بابل د دېوالونو خلاف جنډا اوچته کړئ، د ښار محافظان مضبوط کړئ، او چوکيداران ودروئ او د پټ ګزار دپاره تيارے وکړئ، ځکه چې مالِک خُدائ به خپله منصوبه او مقصد پوره کړى، هغۀ چې څۀ وفرمائيل نو هم هغه به د بابل د خلقو سره وکړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_12.mp3', '', 1761754199, 1761754199),
(45181, 'Jeremiah 51:13', 'Jeremiah', 51, 13, 'اے بابله، تۀ د ډېرو سيندونو په غاړه پروت ښار يې او د مال دولت او تجارت نه ډک يې، خو ستا اَنجام رارسېدلے دے، او ستا د ژوند تار شلېدلے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_13.mp3', '', 1761754199, 1761754199),
(45182, 'Jeremiah 51:14', 'Jeremiah', 51, 14, 'مالِک خُدائ ربُ الافواج په خپل ذات باندې قسم وکړو چې، زۀ به ستاسو ښارونه د دشمنانو نه ډک کړم، لکه څنګه چې يو پټے د مُولخانو نه ډک وى، او هغوئ به په تاسو باندې د فتحې چغې ووهى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_14.mp3', '', 1761754199, 1761754199),
(45183, 'Jeremiah 51:15', 'Jeremiah', 51, 15, '”مالِک خُدائ په خپل قدرت سره زمکه جوړه کړه. او په خپل حکمت سره يې دُنيا قائمه کړه. او په خپل عقل يې آسمانونه خوارۀ کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_15.mp3', '', 1761754199, 1761754199),
(45184, 'Jeremiah 51:16', 'Jeremiah', 51, 16, 'د هغۀ په حُکم باندې آسمان په غرار شى، هغه وريځې د زمکې د يو سر نه تر بل سره پورې خوروى. هغه برېښنا د باران سره رالېږى او د خپلو ذخيرو نه هوا رالوځوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_16.mp3', '', 1761754199, 1761754199),
(45185, 'Jeremiah 51:17', 'Jeremiah', 51, 17, 'د انسان ټول نسلونه بې‌عقله او بې‌علمه دى، هغه کاريګر چې بُتان جوړوى دوئ به د دې بُتانو په وجه وشرميږى، ځکه چې د دوئ بُتان هم دوکه ده او ساه په کښې نشته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_17.mp3', '', 1761754199, 1761754199),
(45186, 'Jeremiah 51:18', 'Jeremiah', 51, 18, 'دا بُتان فضول او د مسخرو څيزونه دى. کله چې د هغوئ د حساب کِتاب ورځ راشى دا به ټول تباه شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_18.mp3', '', 1761754199, 1761754199),
(45187, 'Jeremiah 51:19', 'Jeremiah', 51, 19, 'خو مالِک خُدائ د يعقوب ميراث د دې بُتانو په شان نۀ دے. هغه د هر شى خالق دے، د بنى اِسرائيلو په شمول چې د هغۀ خپل قوم دے. او د هغۀ نوم ربُ الافواج دے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_19.mp3', '', 1761754199, 1761754199),
(45188, 'Jeremiah 51:20', 'Jeremiah', 51, 20, 'مالِک خُدائ فرمائى چې، ”اے بابله، تۀ زما د جنګ تبر يې، او زما د جنګ وسله يې. ستا په ذريعه به زۀ قومونه ذره ذره کوم، او زۀ به په تا بادشاهتونه تباه کوم،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_20.mp3', '', 1761754199, 1761754199),
(45189, 'Jeremiah 51:21', 'Jeremiah', 51, 21, 'زۀ به ستا په ذريعه آسونه او د هغۀ سوارۀ ذره ذره کوم، زۀ به په تا ګاډۍ او د هغې چلوونکى تس نس کوم،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_21.mp3', '', 1761754199, 1761754199),
(45190, 'Jeremiah 51:22', 'Jeremiah', 51, 22, 'زۀ به په تا ښځې او سړى ذره ذره کوم، زۀ به په تا بوډاګان او ځوانان وژنم، زۀ به په تا ځوانان او پېغلې ذره ذره کوم،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_22.mp3', '', 1761754199, 1761754199),
(45191, 'Jeremiah 51:23', 'Jeremiah', 51, 23, 'زۀ به په تا شپونکى او رمې تس نس کوم، زۀ به په تا زميندار او د غوَيانو جوړې ذره ذره کوم، زۀ به په تا حکمرانان او مشران وژنم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_23.mp3', '', 1761754199, 1761754199),
(45192, 'Jeremiah 51:24', 'Jeremiah', 51, 24, '”ستا د سترګو د وړاندې به زۀ بابليانو او څوک چې په بابل کښې اوسيږى د هغوئ د بدو کارونو په بدله کښې چې يې په صيون کښې کړى دى بدله ورکړم،“ مالِک خُدائ فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_24.mp3', '', 1761754199, 1761754199),
(45193, 'Jeremiah 51:25', 'Jeremiah', 51, 25, 'مالِک خُدائ فرمائى چې، ”زۀ ستا په خلاف يم، اے تباه کوونکيه غره، تۀ چې ټوله زمکه تباه کوې. زۀ به خپل لاس ستا په خلاف دراوږد کړم، چې د اوچت ځائ نه دې رانسکور کړم، او چې درنه يو سوزېدلے او د ايرو غر جوړ کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_25.mp3', '', 1761754199, 1761754199),
(45194, 'Jeremiah 51:26', 'Jeremiah', 51, 26, 'ستا نه به يو کاڼے هم راوچت نۀ کړے شى چې د ګوټ کاڼے شى، او نۀ به درنه يو کاڼے د بنياد دپاره استعمال شى، ځکه تۀ به د تل دپاره په خرابه بدل شې. دا د مالِک خُدائ فرمان دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_26.mp3', '', 1761754199, 1761754199),
(45195, 'Jeremiah 51:27', 'Jeremiah', 51, 27, 'په هغه مُلک کښې د بابل خلاف جنډا راوچته کړئ، په قومونو کښې بيګل وغږوئ، قومونه د هغۀ په خلاف د جنګ دپاره تيار کړئ، او دغه بادشاهتونه د هغۀ په خلاف راوچت کړئ يعنې، اراراط، مِنى، او اشکناز بادشاهتونه د هغۀ خلاف راوغواړئ. او د هغۀ خلاف جنګى کمانډر مقرر کړئ، او د هغۀ خلاف دومره آسونه راولئ لکه د مُولخانو پرګله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_27.mp3', '', 1761754199, 1761754199),
(45196, 'Jeremiah 51:28', 'Jeremiah', 51, 28, 'قومونه د بابل خِلاف د جنګ دپاره تيار کړئ. د مادى بادشاهان، د هغوئ حکمرانان او د هغوئ ټول مشران، او هغه ټول مُلکونه چې هغوئ ورباندې حکومت کوى راوغواړئ چې د هغوئ خلاف جنګ وکړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_28.mp3', '', 1761754199, 1761754199),
(45197, 'Jeremiah 51:29', 'Jeremiah', 51, 29, 'زمکه لړزيږى او د دردونو په وجه چورليږى، ځکه چې مالِک خُدائ د بابل په خلاف چې کومه منصوبه تياره کړې ده هغه نۀ بدلېدونکې ده. نو بابل به په خرابه بدل کړے شى او يو کس به هم هلته نۀ اوسيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_29.mp3', '', 1761754199, 1761754199),
(45198, 'Jeremiah 51:30', 'Jeremiah', 51, 30, 'د بابل فوجيانو جنګ بس کړو، او په خپلو برجونو کښې بند پاتې شول. د هغوئ زور ختم شو او هغوئ لکه د ښځو په شان بُزدله شول. حمله کوونکو د هغوئ کورونو ته اور واچولو او د هغوئ د ښار دروازې يې ماتې کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_30.mp3', '', 1761754199, 1761754199),
(45199, 'Jeremiah 51:31', 'Jeremiah', 51, 31, 'قاصدان د يو بل نه مخکښې کيږى او په منډه دى چې د بابل بادشاه ته دا پېغام ورسوى او په دې يې خبر کړى چې د هغۀ ټول ښار قبضه شو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_31.mp3', '', 1761754199, 1761754199),
(45200, 'Jeremiah 51:32', 'Jeremiah', 51, 32, 'دشمن د سيندونو لارې ګودرې د تښتېدلو دپاره بندې کړې دى او په جبو او لوخو يې اور بل کړے دے او د بابل فوجيان يرې راخستى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_32.mp3', '', 1761754199, 1761754199),
(45201, 'Jeremiah 51:33', 'Jeremiah', 51, 33, 'مالِک خُدائ د بنى اِسرائيلو خُدائ پاک داسې فرمائى چې، بابل لکه د درمند په شان تيار دے او اوس هغه وخت رارسېدلے دے چې خلق هغه د پښو لاندې کړى هرکله چې د لو وخت شروع شى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_33.mp3', '', 1761754199, 1761754199),
(45202, 'Jeremiah 51:34', 'Jeremiah', 51, 34, '”نبوکدنضر د بابل بادشاه مونږ لواړ تېر کړُو، او هغۀ مونږ سرګردانه او مات کړُو، هغۀ مونږ لکه د تش منګى په شان يوې خوا ته وغورزولو. لکه د ښامار په شان يې تېر کړُو او زمونږ د ښو غوښو نه يې خپله ګېډه ډکه کړه، او نوره يې بيا د خولې نه تُو کړه.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_34.mp3', '', 1761754199, 1761754199),
(45203, 'Jeremiah 51:35', 'Jeremiah', 51, 35, 'خو اوس دې د صيون اوسېدونکى وائى چې، ”مونږ سره چې کوم ظلم زياتے شوے دے هم هغه شان حالات دې په بابل راشى.“ د يروشلم اوسېدونکى دې وائى چې، ”زمونږ چې کومه وينه توئ شوې ده نو د هغې ذمه وارى دې د بابل په غاړه وى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_35.mp3', '', 1761754199, 1761754199),
(45204, 'Jeremiah 51:36', 'Jeremiah', 51, 36, 'نو په دې وجه مالِک خُدائ داسې فرمائى چې، ”زۀ به ستاسو د حق دفاع وکړم او ستاسو انتقام به واخلم، زۀ به د هغۀ د سيند او چينو اوبۀ اوچې کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_36.mp3', '', 1761754199, 1761754199),
(45205, 'Jeremiah 51:37', 'Jeremiah', 51, 37, 'بابل نه به د تباهۍ ډېرے جوړ شى، او ګيدړان به په کښې غارونه جوړ کړى. هغه به نورو ته د يرې او مسخرو شى، او څوک به هم په کښې نۀ اوسيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_37.mp3', '', 1761754199, 1761754199),
(45206, 'Jeremiah 51:38', 'Jeremiah', 51, 38, 'د بابل ټول خلق به لکه د زمرو په شان شور کوى. او هغه به لکه د زمرو د ورکوټو بچو په شان غريږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_38.mp3', '', 1761754199, 1761754199),
(45207, 'Jeremiah 51:39', 'Jeremiah', 51, 39, 'خو کله چې هغوئ په مستۍ کښې راشى نو زۀ به هغوئ دپاره مېلمستيا وکړم او هغوئ به ښۀ نشه کړم، نو بيا به هغوئ په چغو سورو او خندا ګانو کښې داسې د ټول عمر دپاره اودۀ کړم چې بيا به کله هم راوچت نۀ شى. دا د مالِک خُدائ فرمان دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_39.mp3', '', 1761754199, 1761754199),
(45208, 'Jeremiah 51:40', 'Jeremiah', 51, 40, 'زۀ به هغوئ لکه د ګډورو، چېلو او ګډانو په شان حلالېدو دپاره بوځم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_40.mp3', '', 1761754199, 1761754199),
(45209, 'Jeremiah 51:41', 'Jeremiah', 51, 41, 'مالِک خُدائ د بابل په حقله فرمائى چې، ”د بابل هغه لوئ ښار چې ټولې دُنيا به يې صِفت کولو څنګه شکست وخوړو او قبضه شو، د ټولو قومونو دپاره د بابليانو نه څۀ يروونکے منظر جوړ شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_41.mp3', '', 1761754199, 1761754199),
(45210, 'Jeremiah 51:42', 'Jeremiah', 51, 42, 'سمندر به په بابل راواوړى او د هغۀ زورَورى چپې به بابل پټ کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_42.mp3', '', 1761754199, 1761754199);